/**
 * The HeroUI 3 semantic layer — the Injishi teal theme.
 *
 * This is the SAME kind of artifact as `semantic.ts`: a role -> value map with
 * one authored source. What differs is the VOCABULARY. HeroUI 3 reads its own
 * role names off CSS variables (`--accent`, `--surface`, `--field-background`,
 * …), so a HeroUI component only renders correctly when those exact names
 * resolve. Emitting them here rather than pasting a theme block into five
 * `globals.css` files is what keeps ADR-010's "one semantic source" true after
 * the move to HeroUI.
 *
 * Values are OKLCH, generated by the HeroUI theme builder at
 * base 0.01 / chroma 0.11 / hue 208 / lightness 0.65, radius medium, form
 * radius none. They are transcribed verbatim EXCEPT where a transcribed value
 * fails WCAG — ADR-025 lists all five of those and shows the measurement that
 * moved each one. The rule that pass established: keep the builder's hue and
 * chroma, move only lightness, and only as far as the floor requires.
 *
 * The hue moved from 66 (amber) to 208 (teal) in this pass, and the accent rose
 * from L 0.60 to L 0.65. That second move is why `--accent-foreground` is
 * near-INK again rather than near-white: a fill at L 0.65 carries white at only
 * 3.02:1, and ink at 5.71:1. This restores the pre-HeroUI ink-on-accent rule
 * that ADR-010 recorded and the amber pass had to suspend.
 *
 * FIVE roles are authored here that the builder does not produce, because
 * HeroUI has no role for them and Injishi does:
 *
 *  - `accentText`  — teal as TEXT on a light canvas. `--accent` is a FILL at
 *                    L 0.65; as text on the L 0.9373 tertiary surface it
 *                    measures 2.9:1, under 4.5:1, so a separate darker step is
 *                    required. Same hue, so it reads as one colour.
 *  - `info`        — the fifth status hue. It MOVED from blue `#0379A1` to
 *                    violet hue 285 in this pass, and the reason is the theme
 *                    hue itself: blue at hue 208 IS the accent now, so a blue
 *                    `info` badge was indistinguishable from an accent badge.
 *                    285 is the one gap left between accent 208, success 145,
 *                    warning 67 and danger 20.
 *  - `foregroundHover` — the hover step under the solid neutral button, one
 *                    small move off `foreground`. Aliasing it to `muted` jumped
 *                    a near-black fill to mid-grey.
 *  - `dangerText`  — crimson as TEXT, and the exact counterpart of `accentText`
 *                    one role up. `--danger` is a FILL, tuned so that
 *                    `--danger-foreground` reads ON it; nothing tuned it for
 *                    reading on a surface. Dark `--danger` measures 3.63:1 on
 *                    `--surface`, under the 4.5:1 that binds on the 12px field
 *                    errors in the checkout, which is every "Check that number"
 *                    and "That is an Airtel Money number" a guest sees. Light
 *                    measures 4.75:1 on `surface` but 3.99:1 on `tertiary`, so
 *                    it fails there too. Same hue and chroma as the fill in each
 *                    theme, lightness moved only as far as the floor requires
 *                    (the ADR-025 rule), so the two read as one colour.
 *  - `fieldOutline` — the form-field BOUNDARY. New in ADR-025. `--border` is a
 *                    decorative hairline at 1.24:1 and WCAG 1.4.11 does not
 *                    bind on it; a field outline is a control boundary and 3:1
 *                    does bind. The `input` alias used to point at `border`,
 *                    which meant 33 `border-input` call sites drew a boundary
 *                    nobody with low vision could see. It points here now.
 *
 * NO `*-hover` role is authored here beyond `foregroundHover`. `@heroui/styles`
 * DERIVES every other one from the base role with `color-mix` —
 * `--accent-hover` is `color-mix(in oklab, var(--accent) 90%,
 * var(--accent-foreground) 10%)`, and `--default-hover`, `--danger-hover`,
 * `--field-hover` and the rest follow the same rule. Overriding one with a
 * hand-picked value replaces that derivation for that role alone and quietly
 * breaks the system's one hover convention. Change `--accent` and every hover
 * moves with it.
 *
 * @see semantic.ts for the pre-HeroUI vocabulary, still emitted for the apps
 *      that have not been converted yet.
 * @see ADR-025 for the five WCAG corrections and their measured before/after.
 */

import type { RoleMap } from "./semantic";


/** Roles holding ONE value in both themes (the ADR-010 call 2 rule, kept). */
export const herouiFixed = {
    // A brand chip must not invert. These were the navy ink set; they now sit on
    // the theme's own near-neutral hue so a chip cannot clash with the surface
    // it lands on.
    ink: "oklch(21.03% 0.0059 208.00)",
    white: "#FFFFFF",
    black: "var(--ink)",
    slateLine: "oklch(51.50% 0.0199 208.00)",
    surfaceTint: "oklch(95.24% 0.0080 208.00)",
    canvas: "oklch(97.02% 0.0100 208.00)",
    controlWash: "oklch(51.50% 0.0199 208.00)",
    placeholderDim: "oklch(51.50% 0.0199 208.00)",
} as const satisfies RoleMap;

